SELECT COUNT(*) FROM orders o LEFT JOIN user u ON o.user_id = u.id


        AND (o.order_no LIKE CONCAT('%',#{keyword},'%') OR u.username LIKE CONCAT('%',#{keyword},'%'))

    AND o.status = #{status}

SELECT o.*, u.username FROM orders o LEFT JOIN user u ON o.user_id = u.id


        AND (o.order_no LIKE CONCAT('%',#{keyword},'%') OR u.username LIKE CONCAT('%',#{keyword},'%'))

    AND o.status = #{status}

ORDER BY o.created_at DESC LIMIT #{offset}, #{size}

